function applyAchievementFilters(){
 document.querySelectorAll('[data-ach-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.achFilter===achievementCategoryFilter)));
 document.querySelectorAll('[data-ach-status]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.achStatus===achievementStatusFilter)));
 document.querySelectorAll('[data-ach-category]').forEach(section=>{
  const categoryMatch=achievementCategoryFilter==='all'||section.dataset.achCategory===achievementCategoryFilter;
  let visible=0;
  section.querySelectorAll('[data-ach-state]').forEach(card=>{const stateMatch=achievementStatusFilter==='all'||card.dataset.achState===achievementStatusFilter;card.hidden=!stateMatch;if(stateMatch)visible++;});
  section.hidden=!categoryMatch||visible===0;
 });
}
document.addEventListener('click',e=>{const c=e.target.closest?.('[data-ach-filter]'),st=e.target.closest?.('[data-ach-status]');if(c){achievementCategoryFilter=c.dataset.achFilter;applyAchievementFilters();}if(st){achievementStatusFilter=st.dataset.achStatus;applyAchievementFilters();}});
function cguTopicScore(rec){
 if(rec?.checked)return 1;
 const n=Number(rec?.progress);
 return Number.isFinite(n)?Math.max(0,Math.min(.99,n)):0;
}
function cguPct(value,total){return total?Math.round(value/total*1000)/10:0;}
function cguFmtPct(value){return Number.isInteger(value)?String(value):value.toFixed(1);}
function cguEvidence(rec){
 const rows=Array.isArray(rec?.evidence)?rec.evidence:[];
 if(!rows.length)return '';
 return `<div class="cgu-evidence">${rows.map(x=>`<span class="${x.status==='done'?'done':'partial'}">${esc(x.label)}</span>`).join('')}</div>`;
}
function cguCheckSnapshot(){
 const checked=state.cguCheck?.checked||{};
 const scores=CGU_CHECK_TOPICS.map(t=>({topic:t,rec:checked[t.id],score:cguTopicScore(checked[t.id])}));
 const done=scores.filter(x=>x.rec?.checked).length,partial=scores.filter(x=>!x.rec?.checked&&x.score>0).length,covered=scores.reduce((a,x)=>a+x.score,0);
 const progress=cguPct(covered,CGU_OPERATIONAL_TOTAL);
 const study=(state.sessions||[]).filter(s=>s.date>=CGU_CHECK_START&&s.activity!=='night'),law=(state.legislation?.sessions||[]).filter(s=>s.date>=CGU_CHECK_START);
 const minutes=study.reduce((a,s)=>a+(Number(s.minutes)||0),0)+law.reduce((a,s)=>a+(Number(s.minutes)||0),0);
 const questions=study.reduce((a,s)=>a+(Number(s.questions)||0),0),correct=study.reduce((a,s)=>a+(Number(s.correct)||0),0);
 return {checked,done,partial,covered,progress,minutes,questions,correct,accuracy:questions?Math.round(correct/questions*100):0,days:cguDaysRemaining()};
}
function cguBlockName(block){
 return block==='P1'?'P1 · Conhecimentos Básicos':block==='P2'?'P2 · Conhecimentos Complementares':block==='P3'?'P3 · Conhecimentos Específicos':block;
}
function cguInternalDiscipline(code){
 const m=String(code||'').match(/^(?:CD|[A-Z])(\d+)/);
 return m?'Disciplina '+m[1]:'Disciplina';
}
function cguFriendlyItem(code){
 const text=String(code||''),dot=text.indexOf('.');
 return dot>=0?'Item '+text.slice(dot+1):'Item';
}
function cguCheckPage(){
 const snap=cguCheckSnapshot();
 const groups=CGU_SYLLABUS.map(g=>{
  const groupRows=g.topics.map(t=>({t,rec:snap.checked[t.id],score:cguTopicScore(snap.checked[t.id])}));
  const gd=groupRows.filter(x=>x.rec?.checked).length,gpartial=groupRows.filter(x=>!x.rec?.checked&&x.score>0).length,gscore=groupRows.reduce((a,x)=>a+x.score,0),gpct=cguPct(gscore,g.topics.length);
  return `<details class="card cgu-check-group" ${gd===g.topics.length?'data-complete="true"':''} ${g.id==='B1'?'open':''}><summary><div><span class="badge">${esc(cguBlockName(g.block))}</span><strong>${esc(g.name)}</strong><small>${esc(cguInternalDiscipline(g.id))} · código interno da matriz: ${esc(g.id)} · ${g.officialCount} tópicos/subtópicos · ${gd} concluídos${gpartial?' · '+gpartial+' em andamento':''}</small></div><span class="cgu-group-pct">${cguFmtPct(gpct)}%</span></summary><div class="cgu-topic-list">${groupRows.map(({t,rec,score})=>{const done=!!rec?.checked,partial=!done&&score>0,status=done?(rec.source?.startsWith('auto')?'✓ concluído automaticamente pelo estudo registrado':'✓ concluído manualmente'):partial?`◐ em andamento · ${cguFmtPct(score*100)}% de cobertura reconhecida`:'Marque quando este tópico-mãe e seus subtópicos estiverem cobertos.';return `<label class="cgu-topic ${done?'checked':partial?'partial':''}"><input type="checkbox" data-cgu-check="${esc(t.id)}" ${checks(done)}><span><b>${esc(cguFriendlyItem(t.id))}</b> · ${esc(t.title)}<small>Código interno: ${esc(t.id)} · ${status}</small>${cguEvidence(rec)}</span></label>`;}).join('')}</div></details>`;
 }).join('');
 const historical=snap.checked['B1.4'];
 const historicalCard=historical?.evidence?.length?`<section class="card cgu-history-card"><span class="eyebrow">HISTÓRICO RECUPERADO · DCON</span><h2>O que a Camile já estudou</h2>${cguEvidence(historical)}<p class="muted">Esse avanço veio de registros confirmados anteriormente e foi carregado sem importar horas ou dados do Douglas.</p></section>`:'';
 return heading('EDITAL PUBLICADO · CARGO 1 AUDITORIA','Check - Edital da CGU','Agora o percentual reconhece também cobertura parcial comprovada — sem esperar um tópico-mãe inteiro terminar.')+
 `<section class="card cgu-sunflower-card"><div class="cgu-sunflower-head"><div><span class="eyebrow">AVANÇO DO EDITAL</span><h2>${cguFmtPct(snap.progress)}% de cobertura</h2><p>${snap.done} tópicos-mãe concluídos${snap.partial?' · '+snap.partial+' em andamento':''} · matriz operacional com ${CGU_OPERATIONAL_TOTAL} tópicos-mãe e ${CGU_OFFICIAL_TOTAL} tópicos/subtópicos oficiais.</p></div><div class="sunflower-score">🌻 <b>${cguFmtPct(snap.progress)}%</b></div></div><div class="sunflower-track" aria-label="Progresso do edital: ${cguFmtPct(snap.progress)}%"><div class="sunflower-fill" style="width:${snap.progress}%"></div><span class="sunflower-runner" style="left:${Math.min(98,Math.max(1,snap.progress))}%">🌻</span></div><div class="sunflower-scale"><span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100% · CGU</span></div></section>${historicalCard}<div class="grid metrics four"><div class="card metric"><small>HORAS PARA A CGU</small><strong>${M.hm(snap.minutes)}</strong><span class="sub">Estudo + legislação registrados desde 12/10</span></div><div class="card metric"><small>QUESTÕES</small><strong>${snap.questions}</strong><span class="sub">${snap.correct} acertos registrados</span></div><div class="card metric"><small>PERCENTUAL DE ACERTOS</small><strong>${snap.questions?snap.accuracy+'%':'—'}</strong><span class="sub">Sobre as questões pós-edital registradas</span></div><div class="card metric"><small>DIAS PARA A PROVA</small><strong>${snap.days}</strong><span class="sub">Prova: 13/12/2026</span></div></div><section class="card cgu-check-note"><b>Como ler:</b> a app mostra primeiro a prova e o nome real do conteúdo. B1, C1, A1 etc. são <b>códigos internos da nossa matriz</b>, não siglas oficiais da CGU/Cebraspe. ✓ = tópico concluído; ◐ = cobertura parcial comprovada. Em DCON, o histórico foi preservado sem declarar Art. 5º concluído: ainda constam 23 videoaulas + exercícios pendentes.</section><div class="cgu-check-groups">${groups}</div>`;
}
function prioritiesStatusLabel(lesson,progress){
 if(lesson.status==='NAO_ESTUDAR_DUPLICADO')return 'NÃO ESTUDAR — DUPLICADO';
 if(lesson.status==='CONFERIR_COMPLEMENTO')return 'CONFERIR COMPLEMENTO';
 if(progress.status==='CONCLUIDO')return 'CONCLUÍDO';
 if(progress.status==='EM_ANDAMENTO')return 'EM ANDAMENTO';
 const window=finalCguLessonWindow(lesson,M.day());
 if(window.available)return lesson.status==='ESTUDAR_ULTIMO'?'DISPONÍVEL · ESTUDAR POR ÚLTIMO':'DISPONÍVEL';
 if(window.state==='AGUARDANDO_JANELA')return 'AGUARDANDO +2 DIAS';
 if(lesson.status==='ESTUDAR_ULTIMO')return 'ESTUDAR POR ÚLTIMO';
 if(lesson.availability==='EM_PREPARACAO_NO_PRINT')return 'EM PREPARAÇÃO';
 return 'PENDENTE';
}
function dconPolicyCard(){return '<section class="card"><h2>DCON · teoria obrigatória antes das questões Cebraspe</h2><p>Fonte: <b>Nelma Fontana no Estratégia Concursos</b>. Primeiro, Estratégia Concursos — Nelma Fontana — Aula 04 — Art. 5º — 24 vídeos teóricos + exercícios; depois, <b>Aula 05 · Remédios Constitucionais (8 vídeos)</b> — HC, HD, MS, MI e ação popular.</p><p><b>Sequência obrigatória: Estratégia A04 (24) → Estratégia A05 (8) → voltar à Aula 02 Cebraspe (questões).</b> NÃO ESTUDAR o art. 5º pela Aula 02 Cebraspe como segunda teoria; ela será retomada para questões. As demais aulas Cebraspe continuam depois.</p><p>O progresso antigo da Aula 04 e de DCON permanece preservado. A Aula 05 possui controle próprio dos oito vídeos, sem concluir etapas automaticamente.</p></section>';}
