document.addEventListener('click',e=>{let b=e.target.closest('[data-select],[data-action]');if(!b)return;if(b.dataset.select){selected=b.dataset.select;render();return;}let a=b.dataset.action,id=b.dataset.id;try{if(a==='bizur-record')bizurDialog(id||bizurSnapshot(state).next?.id||'biz-01');if(a==='bizur-toggle'){let snap=bizurSnapshot(state),m=snap.modules.find(x=>x.id===id);if(change(()=>setBizurModuleDone(state,id,!m?.done),m?.done?'Módulo reaberto.':'Módulo BizurAFO marcado como concluído.'))render();}if(a==='bizur-end'){open('<h2>Encerrar intensivão AFO?</h2><p class="muted">O ciclo normal será retomado exatamente do ponto preservado. Nada do BizurAFO ou do Pacelli será apagado.</p><form id="bizur-end-form"><button>Encerrar intensivão e retomar ciclo</button></form>');$('#bizur-end-form').onsubmit=e=>{e.preventDefault();if(change(()=>endBizurFocus(state),'Intensivão encerrado. Ciclo normal retomado.'))close();};}if(a==='bizur-resume'){if(change(()=>resumeBizurFocus(state),'Intensivão AFO retomado.')){selected='afo';render();}}if(a==='reminder-new')reminderDialog();if(a==='goal-complete'){if(change(()=>completeGoal(state,id),'Meta ET concluída. Próxima meta liberada.')){goalView=state.goals.current;render();}}if(a==='motivation-open')motivationDialog();if(a==='session')sessionDialog();if(a==='catalog-study'){selected=b.dataset.subject;sessionDialog({subjectId:b.dataset.subject,unitId:b.dataset.unit,activity:'theory'});}if(a==='andresan-record'){selected='port';sessionDialog({subjectId:'port',activity:'andresan',title:'Andresan · resolução de questões Cebraspe'});}if(a==='night')sessionDialog({subjectId:id,activity:'night',minutes:5});if(a==='go-subject'){selected=currentSubject().id;location.hash='subjects';}if(a==='unit')unitDialog(id);if(a==='checkpoint')checkpointDialog(id);if(a==='quick-battery'){let sid=b.dataset.subject,uid=b.dataset.unit;selected=sid;sessionDialog({subjectId:sid,unitId:uid,activity:'battery'});}if(a==='quick-checkpoint'){selected=b.dataset.subject;checkpointDialog(id);}if(a==='refresh-build')refreshBuild();if(a==='book-record'){const sid=b.dataset.subject||selected;selected=sid;sessionDialog({subjectId:sid,activity:'free',title:(b.dataset.book||'Livro')+' · Capítulo '+(b.dataset.chapter||'')+' — '+(b.dataset.topic||'')});}
if(a==='export')backup();if(a==='import')importDialog();if(a==='import-apply'&&pendingImport){if(pendingImport.base!==storedRaw)throw Error('Os registros mudaram. Selecione o arquivo novamente.');if(change(()=>pendingImport.next,'Importação concluída.',false)){pendingImport=null;close();}}if(a==='cycle-skip-unavailable'){
 if(finalCguIsSunday())throw Error('Domingo não avança o ciclo.');
 if(currentSubject().id!=='cgu7')throw Error('Esta ação só vale para bloco 7 Fontes.');
 const info=sevenFontesInstruction(state.cycle.index);if(info.available)throw Error('Há aula disponível nesta posição; estude-a antes de avançar.');
 if(Number(state.cycle.minutes||0)>0)throw Error('Há tempo acumulado nesta posição. Registre ou finalize esse estudo antes de pular o bloco.');
 change(()=>{const next=M.copy(state);next.cguFinalPlan=next.cguFinalPlan||{};next.cguFinalPlan.unavailableSkips=[...(next.cguFinalPlan.unavailableSkips||[]),{date:M.day(),index:next.cycle.index,slot:finalCguSlot(next.cycle.index).label,reason:'7 Fontes sem aula operacionalmente disponível'}];next.cycle={...next.cycle,index:(next.cycle.index+1)%M.CYCLE.length,minutes:0};return next;},'Posição 7 Fontes indisponível pulada sem criar sessão artificial.',false);
 }
 if(a==='timer-start')startTimer();if(a==='timer-toggle'){timer.elapsed=elapsed();timer.running=!timer.running;timer.started=Date.now();saveTimer();render();}if(a==='timer-save'){if(elapsed()<60000)throw Error('Registre após completar pelo menos um minuto.');timer.elapsed=elapsed();timer.running=false;saveTimer();render();sessionDialog({...timer,minutes:Math.floor(timer.elapsed/60000),fromTimer:true});}if(a==='law-edit')editLawDialog(id);if(a==='law-delete')deleteLawDialog(id);if(a==='law-pair')lawManualDialog(id,15);if(a==='law-manual')lawManualDialog(id||currentLaw()?.id,15);if(a==='law-timer-start'){let n=currentLaw();lawTimer={normId:n.id,elapsed:0,started:Date.now(),running:true};saveLawTimer();render();}if(a==='law-timer-toggle'){lawTimer.elapsed=lawElapsed();lawTimer.running=!lawTimer.running;lawTimer.started=Date.now();saveLawTimer();render();}if(a==='law-timer-save'){if(lawElapsed()<60000)throw Error('Registre após completar pelo menos um minuto.');let mins=Math.max(1,Math.floor(lawElapsed()/60000));lawTimer.elapsed=lawElapsed();lawTimer.running=false;saveLawTimer();lawManualDialog(lawTimer?.normId||currentLaw().id,mins,'timer');lawTimer=null;saveLawTimer();}if(a==='law-complete')completeLawDialog();if(a==='to-solid'){open('<h2>Reduzir carga e entrar no Estudo Sólido</h2><form id="solid-form"><label>Minutos por bloco<input name="minutes" type="number" min="30" max="'+(subject().slotMinutes-1)+'" value="60" required></label><button style="margin-top:18px">Confirmar transição</button></form>');$('#solid-form').onsubmit=e=>{e.preventDefault();if(change(()=>M.switchSolid(state,selected,e.target.elements.minutes.value)))close();};}if(a==='notebook-new'){open('<h2>Novo caderno TEC</h2><form id="notebook-form" class="form-grid"><label class="full">Nome<input name="title" required></label><label class="full">Link TEC<input name="url" type="url" placeholder="https://..."></label><label>Total de questões<input type="number" name="target" min="1" required></label><button class="full">Criar caderno</button></form>');$('#notebook-form').onsubmit=e=>{e.preventDefault();let f=e.target.elements;if(change(()=>M.addNotebook(state,selected,f.title.value,f.url.value,f.target.value)))close();};}if(a==='notebook-round'){let n=subject().notebooks.find(n=>n.id===id);open(`<h2>Concluir rodada</h2><p>${esc(n.title)}</p><form id="round-form" class="form-grid"><label>Questões resolvidas<input type="number" name="attempted" min="0" required value="${n.stage==='main'?n.target:n.stage==='errors'?n.errors:''}"></label><label>Acertos<input type="number" name="correct" min="0" required></label><small class="full">Informe a rodada completa. Nas favoritas, zero é permitido se nenhuma foi marcada.</small><button class="full">Salvar resultados</button></form>`);$('#round-form').onsubmit=e=>{e.preventDefault();if(change(()=>M.notebookRound(state,selected,id,e.target.elements.attempted.value,e.target.elements.correct.value)))close();};}if(a==='csv'){let cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"',rows=[['Data','Disciplina','Aula','Forma','Formato','Início','Fim','Minutos','Questões','Acertos','Notas'],...filteredHistory().map(s=>[s.date,label(s.subjectId),s.title,M.ACTIVITIES[s.activity],s.medium,s.start,s.end,s.minutes,s.questions,s.correct,s.notes])];download('Metodo-ET-diario.csv','\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}}catch(e){toast(e.message,true);}});
document.addEventListener('change',e=>{if(e.target.matches?.('[data-cgu-check]')){const code=e.target.dataset.cguCheck,on=e.target.checked;change(()=>{const next=M.copy(state);next.cguCheck=next.cguCheck||{version:2,startedAt:CGU_CHECK_START,examDate:'2026-12-13',checked:{}};next.cguCheck.checked=next.cguCheck.checked||{};const previous=next.cguCheck.checked[code]||{};if(on)next.cguCheck.checked[code]={...previous,checked:true,progress:1,source:'manual',at:new Date().toISOString()};else if(Number(previous.baselineProgress)>0)next.cguCheck.checked[code]={...previous,checked:false,progress:Number(previous.baselineProgress),source:'historical-camile',at:new Date().toISOString()};else delete next.cguCheck.checked[code];return next;},on?'Tópico marcado como concluído no edital CGU.':'Tópico reaberto no edital CGU.',false);return;}if(e.target.matches?.('[data-reminder-status]')){let f=e.target.closest('form');change(()=>saveReminder(state,{id:f.dataset.reminderForm,text:f.elements.text.value,status:f.elements.status.value}),'Lembrete salvo.');}if(e.target.id?.startsWith('history-'))$('#history-results').innerHTML=historyRows();});
window.addEventListener('hashchange',()=>{render();});
window.addEventListener('storage',e=>{if(e.key===M.KEY){toast('Os dados foram alterados em outra aba. Recarregue para continuar.',true);}});
