function dashboardNumber(n){return Number(n||0).toLocaleString('pt-BR');}
function dashboardPercent(n){return n===null||n===undefined?'—':Number(n).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%';}
function compareValue(current,previous,formatter){
 const diff=current-previous,word=diff===0?'igual a ontem':diff>0?'acima de ontem':'abaixo de ontem';
 return `<strong>${formatter(current)}</strong><span class="sub">Ontem: ${formatter(previous)} · ${word}</span>`;
}
function progressFilters(){
 const periods=[['all','Desde o início'],['30','Últimos 30 dias'],['7','Últimos 7 dias'],['month','Mês atual']],showPeriod=['overview','disciplines'].includes(progressView);
 return `<section class="progress-toolbar"><div class="progress-view-tabs" role="tablist" aria-label="Visões de progresso">${[['overview','Visão Geral'],['disciplines','Disciplinas'],['evolution','Evolução'],['method','Método ET']].map(([id,title])=>`<button class="secondary" data-progress-view="${id}" aria-pressed="${progressView===id}">${title}</button>`).join('')}</div><div class="progress-filter-row">${showPeriod?`<label>Período<select id="progress-period">${periods.map(([id,title])=>option(id,title,progressPeriod)).join('')}</select></label>`:''}<label>Disciplina<select id="progress-subject">${option('all','Todas as disciplinas',progressSubject)}${['afo','dad','ti','port','dcon'].map(id=>option(id,label(id),progressSubject)).join('')}</select></label></div><p class="progress-principle">Sem pesos e sem comparação externa: <b>todas as disciplinas têm o mesmo valor.</b> A referência é sempre o seu próprio histórico.</p></section>`;
}
function activityBars(items){
 const total=items.reduce((a,x)=>a+x.minutes,0);
 if(!items.length)return '<div class="empty">Ainda não há atividades registradas neste recorte.</div>';
 return `<div class="analysis-bars">${items.map(x=>{let pct=total?x.minutes/total*100:0;return `<div class="analysis-bar-row"><div><b>${esc(x.label)}</b><span>${M.hm(x.minutes)} · ${pct.toLocaleString('pt-BR',{maximumFractionDigits:1})}%</span></div><progress value="${x.minutes}" max="${total||1}"></progress></div>`;}).join('')}</div>`;
}
function subjectTimeBars(rows){
 const max=Math.max(1,...rows.map(x=>x.minutes));
 return `<div class="analysis-bars">${rows.map(x=>`<div class="analysis-bar-row"><div><b>${label(x.id)}</b><span>${M.hm(x.minutes)}</span></div><progress value="${x.minutes}" max="${max}"></progress></div>`).join('')}</div>`;
}
function trendBars(series,key,formatter){
 const max=Math.max(1,...series.map(x=>Number(x[key])||0));
 return `<div class="trend-chart" role="img" aria-label="Evolução do indicador"><div class="trend-columns">${series.map(x=>{const value=Number(x[key])||0,height=value?Math.max(5,value/max*100):1;return `<div class="trend-column" title="${esc(x.label)} · ${esc(formatter(value))}"><span class="trend-value">${esc(formatter(value))}</span><i style="height:${height}%"></i><small>${esc(x.label)}</small></div>`;}).join('')}</div></div>`;
}
function progressOverview(a){
 const p=progressMetrics(state),subjectTitle=progressSubject==='all'?'Todas as disciplinas':label(progressSubject);
 return `<div class="grid metrics performance-metrics"><section class="card metric"><small>HORAS LÍQUIDAS · ${esc(a.bounds.label)}</small><strong>${M.hm(a.metrics.minutes)}</strong><span class="sub">${a.metrics.sessions} sessões · ${a.metrics.days} dias com estudo</span></section><section class="card metric"><small>QUESTÕES RESOLVIDAS</small><strong>${dashboardNumber(a.metrics.questions)}</strong><span class="sub">${dashboardNumber(a.metrics.correct)} acertos registrados</span></section><section class="card metric"><small>APROVEITAMENTO</small><strong>${dashboardPercent(a.metrics.accuracy)}</strong><span class="sub">Média ponderada das questões registradas</span></section><section class="card metric"><small>MÉDIA POR DIA ESTUDADO</small><strong>${M.hm(a.metrics.avgDaily)}</strong><span class="sub">${esc(subjectTitle)} · dias com sessão registrada</span></section></div>
 <section class="card self-compare section-title"><div class="page-head"><div><span class="eyebrow">VOCÊ CONTRA VOCÊ</span><h2>Hoje x ontem</h2><p>Sem ranking externo. A única referência é o que você construiu ontem.</p></div><span class="badge">${a.yesterday.split('-').reverse().join('/')}</span></div><div class="grid self-compare-grid"><article class="metric mini"><small>HORAS</small>${compareValue(a.todayStats.minutes,a.yesterdayStats.minutes,M.hm)}</article><article class="metric mini"><small>QUESTÕES</small>${compareValue(a.todayStats.questions,a.yesterdayStats.questions,dashboardNumber)}</article><article class="metric mini"><small>APROVEITAMENTO</small><strong>${dashboardPercent(a.todayStats.accuracy)}</strong><span class="sub">Ontem: ${dashboardPercent(a.yesterdayStats.accuracy)}</span></article></div></section>
 <div class="grid two section-title"><section class="card"><h2>Tempo por disciplina</h2><p class="muted">Distribuição do tempo líquido no período selecionado.</p>${subjectTimeBars(a.filteredSubjects)}</section><section class="card"><h2>Como você estudou</h2><p class="muted">Distribuição por tipo de atividade registrada.</p>${activityBars(a.activity)}</section></div>
 <section class="intensity-wrap section-title" aria-label="Lembrete de mentalidade"><article class="card intensity-card"><span class="intensity-mark" aria-hidden="true">✦</span><p>A intensidade <strong>distorce a realidade.</strong></p></article></section>
 <div class="grid two section-title"><section class="card"><h2>Constância acumulada</h2><div class="statline"><span><b>${p.streak.days}</b> dias de estudo</span><span><b>${p.streak.best}</b> dias no seu recorde</span></div><p class="muted progress-explanation">A sequência mede presença no estudo. Domingo de descanso não interrompe a sequência; domingo estudado conta.</p></section><section class="card"><h2>Princípio da Central</h2><p class="muted progress-explanation">Nenhuma disciplina recebe peso maior. Horas, questões e etapas são mostradas para você enxergar a sua própria execução — não para criar uma nota artificial de “chance de aprovação”.</p></section></div>`;
}
function reviewUnitsForSubject(s){
 const ids=new Set(state.sessions.filter(x=>x.subjectId===s.id&&x.unitId&&(x.activity==='micro'||x.activity==='general'||(x.activity==='free'&&/revis/i.test((x.title||'')+' '+(x.notes||''))))).map(x=>x.unitId));
 return M.methodUnits(s).filter(u=>ids.has(u.id)).length;
}
function layeredSubjectProgress(s){
 const units=M.methodUnits(s),total=Math.max(1,units.length),theory=units.filter(u=>u.theoryDone).length,review=reviewUnitsForSubject(s),battery=units.filter(u=>u.batteryDone).length,checkpoint=M.checkpoints(s).filter(cp=>cp.status==='done').reduce((n,cp)=>n+cp.units.length,0);
 const stages=[['Teoria',theory,'theory'],['Revisão',review,'review'],['Bateria',battery,'battery'],['Checkpoint',checkpoint,'checkpoint']];
 return `<article class="layer-subject subject-${s.id}"><div class="layer-head"><b>${label(s.id)}</b><small>${esc(s.course||'')}</small></div><div class="layer-stack">${stages.map(([name,value,cls])=>`<div class="layer-row ${cls}"><span>${name}</span><div><i style="width:${Math.min(100,value/total*100)}%"></i></div><b>${value}/${units.length}</b></div>`).join('')}</div></article>`;
}
function progressDisciplines(a){
 const rows=a.filteredSubjects,maxQuestions=Math.max(1,...a.filteredSubjects.map(x=>x.questions)),visible=rows.map(d=>subject(d.id)).filter(Boolean);
 return `<section class="card layered-progress"><div class="page-head"><div><span class="eyebrow">PROGRESSO MULTICAMADA</span><h2>Teoria → Revisão → Bateria → Checkpoint</h2><p>Cada disciplina mantém uma cor-base; os tons mostram as camadas já consolidadas.</p></div></div><div class="layer-grid">${visible.map(layeredSubjectProgress).join('')}</div><p class="muted progress-explanation">Revisão considera microrrevisões, revisão geral e registros livres identificados como revisão. Checkpoint é convertido em unidades cobertas para manter a leitura comparável.</p></section>
 <section class="card section-title"><div class="page-head"><div><h2>Desempenho por disciplina</h2><p>Horas, questões e avanço real do Método ET no mesmo lugar.</p></div><span class="badge">${esc(a.bounds.label)}</span></div><div class="table-wrap"><table class="performance-table"><thead><tr><th>DISCIPLINA</th><th>HORAS</th><th>QUESTÕES</th><th>ACERTOS</th><th>%</th><th>TEORIA</th><th>BATERIAS</th><th>CHECKPOINTS</th><th>FASE</th><th>ÚLTIMO CONTATO</th></tr></thead><tbody>${rows.map(d=>`<tr><td><b>${label(d.id)}</b><small>${esc(d.course||'')}</small></td><td>${M.hm(d.minutes)}</td><td>${dashboardNumber(d.questions)}</td><td>${dashboardNumber(d.correct)}</td><td>${dashboardPercent(d.accuracy)}</td><td>${d.theory}/${d.total}<small>${dashboardPercent(d.theoryPct)}</small></td><td>${d.batteries}/${d.total}<small>${dashboardPercent(d.batteryPct)}</small></td><td>${d.cpDone}/${d.checkpoints}<small>${dashboardPercent(d.checkpointPct)}</small></td><td><span class="badge">${d.phase==='solid'?'Estudo Sólido':'Estudo Novo'}</span></td><td>${d.lastContact?d.lastContact.split('-').reverse().join('/'):'—'}<small>${d.daysSince===null?'Sem registro':d.daysSince+' dias'}</small></td></tr>`).join('')}</tbody></table></div></section>
 <div class="grid two section-title"><section class="card"><h2>Horas por disciplina</h2><p class="muted">Sem ranking: apenas uma fotografia de distribuição.</p>${subjectTimeBars(rows)}</section><section class="card"><h2>Questões e aproveitamento</h2><div class="analysis-bars">${rows.map(d=>`<div class="analysis-bar-row"><div><b>${label(d.id)}</b><span>${dashboardNumber(d.questions)} questões · ${dashboardPercent(d.accuracy)}</span></div><progress value="${d.questions}" max="${maxQuestions}"></progress></div>`).join('')}</div><p class="muted progress-explanation">Quando não há questões registradas, a plataforma mostra “—” no aproveitamento em vez de tratar ausência de amostra como 0%.</p></section></div>`;
}
function comparisonCard(title,current,previous,formatter){
 const diff=current-previous,delta=diff===0?'Sem variação':(diff>0?'+':'-')+formatter(Math.abs(diff));
 return `<article class="card metric comparison-metric"><small>${title}</small><strong>${formatter(current)}</strong><span class="sub">Período anterior: ${formatter(previous)}</span><span class="comparison-delta ${diff>0?'up':diff<0?'down':'same'}">${esc(delta)}</span></article>`;
}
function progressEvolution(a){
 return `<div class="grid progress-comparisons">${comparisonCard('SEMANA ATUAL · HORAS',a.weekCurrent.minutes,a.weekPrevious.minutes,M.hm)}${comparisonCard('SEMANA ATUAL · QUESTÕES',a.weekCurrent.questions,a.weekPrevious.questions,dashboardNumber)}${comparisonCard('MÊS ATUAL · HORAS',a.monthCurrent.minutes,a.monthPrevious.minutes,M.hm)}${comparisonCard('MÊS ATUAL · QUESTÕES',a.monthCurrent.questions,a.monthPrevious.questions,dashboardNumber)}</div>
 <div class="grid two section-title"><section class="card trend-card"><h2>Horas por semana</h2><p class="muted">Últimas oito semanas · comparação apenas com o seu próprio histórico.</p>${trendBars(a.weekly,'minutes',M.hm)}</section><section class="card trend-card"><h2>Questões por semana</h2><p class="muted">Volume registrado nas últimas oito semanas.</p>${trendBars(a.weekly,'questions',dashboardNumber)}</section></div>
 <section class="card section-title trend-card"><h2>Evolução mensal</h2><p class="muted">Seis meses de carga líquida estudada.</p>${trendBars(a.monthly,'minutes',M.hm)}</section>`;
}
function methodStageBar(name,value,total){
 return `<div class="method-stage"><div><span>${name}</span><b>${value}/${total}</b></div><progress value="${value}" max="${total||1}"></progress></div>`;
}
function progressMethod(a){
 const rows=a.filteredSubjects;
 return `<section class="method-map">${rows.map(d=>`<article class="card method-subject-card"><div class="method-subject-head"><div><span class="eyebrow">${d.phase==='solid'?'ESTUDO SÓLIDO':'ESTUDO NOVO'}</span><h2>${label(d.id)}</h2><p>${esc(d.nextAction)}</p></div>${d.canSolid&&d.phase!=='solid'?'<span class="badge">Pronto para avançar</span>':''}</div><div class="method-stages">${methodStageBar('Teoria',d.theory,d.total)}${methodStageBar('Baterias',d.batteries,d.total)}${methodStageBar('Checkpoints',d.cpDone,d.checkpoints)}${methodStageBar('Revisão geral',d.general,d.total)}${methodStageBar('Material',d.material,d.total)}</div><a href="#subjects">Abrir disciplinas →</a></article>`).join('')}</section>
 <section class="card section-title"><div class="page-head"><div><h2>Pontos de atenção</h2><p>Fatos operacionais do seu método — sem notas e sem comparar disciplinas entre si.</p></div><span class="badge">${a.attention.length}</span></div>${a.attention.length?`<div class="attention-list">${a.attention.map(x=>`<article class="attention-item ${x.tone}"><div><b>${label(x.subjectId)} · ${esc(x.title)}</b><p>${esc(x.detail)}</p></div></article>`).join('')}</div>`:'<div class="empty">Nenhum ponto operacional pendente detectado neste momento.</div>'}</section>`;
}
function progressPage(){
 const a=analyticsSnapshot(state,{period:progressPeriod,subjectId:progressSubject});
 const body=progressView==='disciplines'?progressDisciplines(a):progressView==='evolution'?progressEvolution(a):progressView==='method'?progressMethod(a):progressOverview(a);
 const head=`<div class="page-head progress-page-head"><div><span class="eyebrow">VOCÊ CONTRA VOCÊ</span><span class="process-focus">FOCO NO PROCESSO!</span><h1>Central de Desempenho</h1><p>Acompanhe sua evolução sem comparação externa. O objetivo é superar o seu próprio ontem.</p></div>${actionsButton('+ Registrar estudo','session')}</div>`;
 return head+progressFilters()+body;
}
